add_action( 'woocommerce_before_single_product', 'perfectpixel_prev_next_product_links', 20 );

function perfectpixel_prev_next_product_links() {
	$prev = get_adjacent_post( true, '', true, 'product_cat' );
	$next = get_adjacent_post( true, '', false, 'product_cat' );
	if ( ! $prev && ! $next ) {
		return;
	}
	echo '<nav class="perfectpixel-product-nav" style="display:flex;justify-content:space-between;margin-bottom:1.5em">';
	echo $prev ? '<a href="' . esc_url( get_permalink( $prev ) ) . '" title="' . esc_attr( get_the_title( $prev ) ) . '">' . esc_html( '{{prev_product_text}}' ) . '</a>' : '<span></span>';
	echo $next ? '<a href="' . esc_url( get_permalink( $next ) ) . '" title="' . esc_attr( get_the_title( $next ) ) . '">' . esc_html( '{{next_product_text}}' ) . '</a>' : '<span></span>';
	echo '</nav>';
}
